package tovo.gestion.rh.conge.service;

import lombok.RequiredArgsConstructor;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import tovo.gestion.rh.utilisateur.repository.UtilisateurRepository;
import tovo.gestion.rh.workflow.service.NotificationService;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tovo.gestion.rh.conge.dto.DemandeCongeRequest;
import tovo.gestion.rh.conge.event.*;

import java.math.*;
import java.sql.Date;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;

@Service @RequiredArgsConstructor
public class DemandeCongeService {
    private final JdbcTemplate jdbc;
    private final ApplicationEventPublisher events;
    private final UtilisateurRepository utilisateurs;
    private final NotificationService notifications;

    @Transactional public Map<String,Object> creer(String email,DemandeCongeRequest r){
        verifierDates(r);verifierPeriodeOuverte(r.dateDebut(),r.dateFin());long emp=employeConnecte(email);Map<String,Object> type=type(r.typeCongeId());BigDecimal jours=calculerJours(emp,r.dateDebut(),r.dateFin(),r.demiJourneeDebut(),r.demiJourneeFin(),(String)type.get("unite_decompte"));
        verifierDuree(type,jours);Long id=jdbc.queryForObject("INSERT INTO demande_conge(employe_id,type_conge_id,date_debut,date_fin,demi_journee_debut,demi_journee_fin,nb_jours,motif,statut) VALUES(?,?,?,?,?,?,?,?,'BROUILLON') RETURNING id",Long.class,emp,r.typeCongeId(),r.dateDebut(),r.dateFin(),r.demiJourneeDebut(),r.demiJourneeFin(),jours,r.motif());return demande(id);
    }
    @Transactional public Map<String,Object> soumettre(long id,String email){
        Map<String,Object> d=demandeVerrouillee(id);if(!"BROUILLON".equals(d.get("statut")))throw new IllegalStateException("Seul un brouillon peut être soumis");long emp=num(d,"employe_id");if(employeConnecte(email)!=emp)throw new AccessDeniedException("Cette demande ne vous appartient pas");LocalDate du=date(d,"date_debut"),au=date(d,"date_fin");verifierPeriodeOuverte(du,au);
        long typeId=num(d,"type_conge_id");Map<String,Object> type=type(typeId);BigDecimal jours=calculerJours(emp,du,au,bool(d,"demi_journee_debut"),bool(d,"demi_journee_fin"),(String)type.get("unite_decompte"));if(jours.signum()<=0)throw new IllegalArgumentException("La période ne contient aucun jour de travail");verifierDuree(type,jours);verifierRegles(emp,typeId,du,au,jours);
        long sid=soldeVerrouille(emp,typeId,du.getYear());BigDecimal reste=BigDecimal.ZERO;if(Boolean.TRUE.equals(type.get("debite_solde"))){Map<String,Object> s=jdbc.queryForMap("SELECT acquis,pris,en_attente,reporte,ajuste FROM solde_conge WHERE id=? FOR UPDATE",sid);BigDecimal disponible=dec(s,"acquis").add(dec(s,"reporte")).add(dec(s,"ajuste")).subtract(dec(s,"pris")).subtract(dec(s,"en_attente"));if(disponible.compareTo(jours)<0&&!Boolean.TRUE.equals(type.get("solde_negatif_autorise")))throw new IllegalStateException("Solde disponible insuffisant");reste=disponible.subtract(jours);}
        try{jdbc.update("UPDATE demande_conge SET statut='SOUMISE',nb_jours=?,date_soumission=CURRENT_TIMESTAMP WHERE id=?",jours,id);}catch(org.springframework.dao.DataIntegrityViolationException ex){throw new IllegalStateException("Une demande ou absence chevauche cette période");}
        if(Boolean.TRUE.equals(type.get("debite_solde"))){mouvement(sid,"RESERVATION",jours,id,"Réservation à la soumission",email,"DEMANDE:"+id+":RESERVATION");jdbc.update("UPDATE solde_conge SET en_attente=en_attente+? WHERE id=?",jours,sid);BigDecimal threshold=jdbc.queryForObject("SELECT seuil_solde_faible_jours FROM politique_demande_conge WHERE id=1",BigDecimal.class);if(reste.compareTo(threshold)<=0)notifierEmploye(emp,"Votre solde de congé est faible : "+reste+" jour(s) restant(s).");}
        notifierManager(emp,"Une demande de congé de "+jours+" jour(s) est à valider.");
        return demande(id);
    }
    @Transactional public Map<String,Object> validerManager(long id,String email){Map<String,Object>d=demandeVerrouillee(id);if(!"SOUMISE".equals(d.get("statut")))throw new IllegalStateException("La demande n'est pas en attente du manager");verifierPeriodeOuverte(date(d,"date_debut"),date(d,"date_fin"));if(!managerAutorise(num(d,"employe_id"),email,date(d,"date_debut")))throw new AccessDeniedException("Seul le manager du demandeur ou son délégué peut valider");int uid=userId(email);jdbc.update("UPDATE demande_conge SET statut='VALIDEE_MANAGER',valide_manager_id=?,date_validation_manager=CURRENT_TIMESTAMP WHERE id=?",uid,id);notifierEmploye(num(d,"employe_id"),"Votre demande de congé a été validée par le manager et transmise à la RH.");return demande(id);}
    @Transactional public Map<String,Object> validerRh(long id,String email){Map<String,Object>d=demandeVerrouillee(id);if(!"VALIDEE_MANAGER".equals(d.get("statut")))throw new IllegalStateException("La validation du manager est requise");verifierPeriodeOuverte(date(d,"date_debut"),date(d,"date_fin"));long type=num(d,"type_conge_id"),emp=num(d,"employe_id");Map<String,Object>t=type(type);int uid=userId(email);
        if(Boolean.TRUE.equals(t.get("debite_solde"))){long sid=soldeVerrouille(emp,type,date(d,"date_debut").getYear());jdbc.queryForMap("SELECT id FROM solde_conge WHERE id=? FOR UPDATE",sid);BigDecimal n=dec(d,"nb_jours");int updated=jdbc.update("UPDATE solde_conge SET en_attente=en_attente-?,pris=pris+? WHERE id=? AND en_attente>=?",n,n,sid,n);if(updated==0)throw new IllegalStateException("La réservation du solde est absente ou incohérente");mouvement(sid,"PRISE",n,id,"Congé validé par la RH",email,"DEMANDE:"+id+":PRISE");}
        jdbc.update("UPDATE demande_conge SET statut='VALIDEE_RH',valide_rh_id=?,date_validation_rh=CURRENT_TIMESTAMP,nb_jours=? WHERE id=?",uid,dec(d,"nb_jours"),id);
        events.publishEvent(new CongeValideEvent(id,emp,type,date(d,"date_debut"),date(d,"date_fin"),dec(d,"nb_jours")));notifierEmploye(emp,"Votre demande de congé a été validée par la RH.");return demande(id);
    }
    @Transactional public Map<String,Object> refuser(long id,String email,String motif){if(motif==null||motif.isBlank())throw new IllegalArgumentException("Le motif du refus est obligatoire");Map<String,Object>d=demandeVerrouillee(id);String status=(String)d.get("statut");if(!Set.of("SOUMISE","VALIDEE_MANAGER").contains(status))throw new IllegalStateException("Cette demande ne peut plus être refusée");verifierPeriodeOuverte(date(d,"date_debut"),date(d,"date_fin"));if(status.equals("SOUMISE")&&!managerAutorise(num(d,"employe_id"),email,date(d,"date_debut")))throw new AccessDeniedException("Action réservée au manager ou à son délégué");if(status.equals("VALIDEE_MANAGER")&&!rh(email))throw new AccessDeniedException("Action réservée à la RH");libererReservation(d,email,"Refus : "+motif);jdbc.update("UPDATE demande_conge SET statut='REFUSEE',motif_refus=? WHERE id=?",motif,id);notifierEmploye(num(d,"employe_id"),"Votre demande de congé a été refusée : "+motif);return demande(id);}
    @Transactional public Map<String,Object> annuler(long id,String email){Map<String,Object>d=demandeVerrouillee(id);String status=(String)d.get("statut");long emp=num(d,"employe_id");verifierPeriodeOuverte(date(d,"date_debut"),date(d,"date_fin"));if(Set.of("SOUMISE","VALIDEE_MANAGER").contains(status)){if(employeConnecte(email)!=emp)throw new AccessDeniedException("Cette demande ne vous appartient pas");libererReservation(d,email,"Annulation par le salarié");}
        else if("VALIDEE_RH".equals(status)){if(!rh(email))throw new AccessDeniedException("L'annulation d'un congé validé est réservée à la RH");Map<String,Object> type=type(num(d,"type_conge_id"));BigDecimal joursRestants=joursRestants(d);if(Boolean.TRUE.equals(type.get("debite_solde"))&&joursRestants.signum()>0){long sid=soldeVerrouille(emp,num(d,"type_conge_id"),date(d,"date_debut").getYear());jdbc.update("UPDATE solde_conge SET pris=GREATEST(0,pris-?) WHERE id=?",joursRestants,sid);mouvement(sid,"LIBERATION",joursRestants,id,"Recrédit après annulation RH",email,"DEMANDE:"+id+":ANNULATION");}events.publishEvent(new CongeAnnuleEvent(id,emp,date(d,"date_debut"),date(d,"date_fin")));}
        else throw new IllegalStateException("Cette demande ne peut pas être annulée");jdbc.update("UPDATE demande_conge SET statut='ANNULEE' WHERE id=?",id);notifierEmploye(emp,"Votre demande de congé a été annulée.");return demande(id);}

    public List<Map<String,Object>> lister(String email,String role,String statut,LocalDate du,LocalDate au,Integer departement){StringBuilder sql=new StringBuilder("SELECT d.*,t.code AS type_code,t.libelle AS type_libelle,c.nom AS employe_nom,c.prenom AS employe_prenom FROM demande_conge d JOIN type_conge t ON t.id=d.type_conge_id JOIN employe e ON e.id=d.employe_id JOIN candidat c ON c.id=e.candidat_id WHERE 1=1");List<Object> args=new ArrayList<>();if("EMPLOYE".equals(role)){sql.append(" AND d.employe_id=?");args.add(employeConnecte(email));}else if("MANAGER".equals(role)){sql.append(" AND d.employe_id IN (WITH RECURSIVE equipe(id) AS (SELECT e.id FROM employe e JOIN candidat c ON c.id=e.candidat_id WHERE lower(c.email)=lower(?) UNION SELECT a.employe_id FROM affectation a JOIN equipe x ON x.id=a.manager_id WHERE a.date_affectation<=CURRENT_DATE AND (a.date_fin IS NULL OR a.date_fin>=CURRENT_DATE)) SELECT id FROM equipe)");args.add(email);}if(statut!=null){sql.append(" AND d.statut=?");args.add(statut);}if(du!=null){sql.append(" AND d.date_fin>=?");args.add(du);}if(au!=null){sql.append(" AND d.date_debut<=?");args.add(au);}if(departement!=null){sql.append(" AND EXISTS(SELECT 1 FROM affectation a WHERE a.employe_id=d.employe_id AND a.departement_id=? AND a.date_affectation<=d.date_debut AND (a.date_fin IS NULL OR a.date_fin>=d.date_debut))");args.add(departement);}sql.append(" ORDER BY d.date_soumission DESC NULLS LAST,d.id DESC");return jdbc.queryForList(sql.toString(),args.toArray());}

    public List<Map<String,Object>> calendrierEquipe(int departement,LocalDate du,LocalDate au,String managerEmail){if(au.isBefore(du))throw new IllegalArgumentException("La période est invalide");String sql="SELECT d.id AS \"demandeId\",d.employe_id AS \"employeId\",c.nom AS \"nom\",c.prenom AS \"prenom\",t.code AS \"typeCode\",t.libelle AS \"typeConge\",d.date_debut AS \"dateDebut\",d.date_fin AS \"dateFin\",d.nb_jours AS \"nbJours\" FROM demande_conge d JOIN type_conge t ON t.id=d.type_conge_id JOIN employe e ON e.id=d.employe_id JOIN candidat c ON c.id=e.candidat_id JOIN affectation a ON a.employe_id=e.id AND a.departement_id=? AND a.date_affectation<=d.date_fin AND (a.date_fin IS NULL OR a.date_fin>=d.date_debut) WHERE d.statut='VALIDEE_RH' AND d.date_debut<=? AND d.date_fin>=?";if(managerEmail!=null)sql="WITH RECURSIVE equipe(id) AS (SELECT e.id FROM employe e JOIN candidat c ON c.id=e.candidat_id WHERE lower(c.email)=lower(?) UNION SELECT af.employe_id FROM affectation af JOIN equipe x ON x.id=af.manager_id WHERE af.date_affectation<=CURRENT_DATE AND (af.date_fin IS NULL OR af.date_fin>=CURRENT_DATE)) "+sql+" AND e.id IN (SELECT id FROM equipe)";sql+=" ORDER BY d.date_debut,c.nom,c.prenom";return managerEmail==null?jdbc.queryForList(sql,departement,au,du):jdbc.queryForList(sql,managerEmail,departement,au,du);}

    public List<Map<String,Object>> delegations(String email){long manager=employeConnecte(email);return jdbc.queryForList("SELECT d.id,d.delegue_id AS \"delegueId\",c.prenom,c.nom,d.date_debut AS \"dateDebut\",d.date_fin AS \"dateFin\" FROM delegation_validation d JOIN employe e ON e.id=d.delegue_id JOIN candidat c ON c.id=e.candidat_id WHERE d.manager_id=? ORDER BY d.date_debut DESC",manager);}
    @Transactional public Map<String,Object> ajouterDelegation(String email,long delegate,LocalDate du,LocalDate au){if(au.isBefore(du))throw new IllegalArgumentException("La date de fin doit suivre la date de début");long manager=employeConnecte(email);if(manager==delegate)throw new IllegalArgumentException("Le manager ne peut pas se déléguer à lui-même");Boolean teammate=jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM affectation WHERE employe_id=? AND manager_id=? AND date_affectation<=? AND (date_fin IS NULL OR date_fin>=?))",Boolean.class,delegate,manager,au,du);if(!Boolean.TRUE.equals(teammate))throw new AccessDeniedException("Le délégué doit appartenir à votre équipe sur la période");Long id=jdbc.queryForObject("INSERT INTO delegation_validation(manager_id,delegue_id,date_debut,date_fin) VALUES(?,?,?,?) RETURNING id",Long.class,manager,delegate,du,au);return jdbc.queryForMap("SELECT d.id,d.delegue_id AS \"delegueId\",c.prenom,c.nom,d.date_debut AS \"dateDebut\",d.date_fin AS \"dateFin\" FROM delegation_validation d JOIN employe e ON e.id=d.delegue_id JOIN candidat c ON c.id=e.candidat_id WHERE d.id=?",id);}
    @Transactional public void supprimerDelegation(String email,long id){long manager=employeConnecte(email);if(jdbc.update("DELETE FROM delegation_validation WHERE id=? AND manager_id=?",id,manager)==0)throw new AccessDeniedException("Délégation introuvable ou non autorisée");}

    @Scheduled(cron="0 0 9 * * *",zone="Indian/Antananarivo") @Transactional public void rappelerValidations(){int days=jdbc.queryForObject("SELECT rappel_validation_jours FROM politique_demande_conge WHERE id=1",Integer.class);LocalDate today=LocalDate.now(ZoneId.of("Indian/Antananarivo"));var rows=jdbc.queryForList("SELECT id,employe_id,statut,date_soumission::date AS submitted,date_validation_manager::date AS manager_date FROM demande_conge WHERE statut IN ('SOUMISE','VALIDEE_MANAGER') AND COALESCE(date_validation_manager,date_soumission)<=CURRENT_DATE-?",days);for(var r:rows){long id=num(r,"id"),emp=num(r,"employe_id");String stage="SOUMISE".equals(r.get("statut"))?"MANAGER":"RH";int inserted=jdbc.update("INSERT INTO demande_rappel_validation(demande_id,role_cible,date_rappel) VALUES(?,?,?) ON CONFLICT DO NOTHING",id,stage,today);if(inserted==0)continue;if(stage.equals("MANAGER"))notifierManager(emp,"Rappel : la demande de congé #"+id+" attend votre validation.");else notifications.notifyRole("RH","Rappel : la demande de congé #"+id+" attend la validation RH.",null);}}

    private void notifierEmploye(long emp,String message){jdbc.query("SELECT u.id FROM utilisateur u JOIN candidat c ON lower(c.email)=lower(u.email) JOIN employe e ON e.candidat_id=c.id WHERE e.id=?",rs->{while(rs.next())utilisateurs.findById((long)rs.getInt(1)).ifPresent(u->notifications.notifyUser(u,message,null));},emp);}
    private void notifierManager(long emp,String message){List<Integer> ids=jdbc.queryForList("SELECT DISTINCT u.id FROM affectation a JOIN employe m ON m.id=a.manager_id JOIN candidat c ON c.id=m.candidat_id JOIN utilisateur u ON lower(u.email)=lower(c.email) WHERE a.employe_id=? AND a.date_affectation<=CURRENT_DATE AND (a.date_fin IS NULL OR a.date_fin>=CURRENT_DATE)",Integer.class,emp);if(ids.isEmpty()){notifications.notifyRole("RH",message,null);return;}for(Integer id:ids)utilisateurs.findById(id.longValue()).ifPresent(u->notifications.notifyUser(u,message,null));}
    private void verifierPeriodeOuverte(LocalDate du,LocalDate au){List<Map<String,Object>> periods=jdbc.queryForList("SELECT statut FROM periode_temps p WHERE make_date(p.annee::int,p.mois::int,1)<=? AND (make_date(p.annee::int,p.mois::int,1)+INTERVAL '1 month - 1 day')::date>=? FOR UPDATE",au,du);if(periods.stream().anyMatch(p->!"OUVERTE".equals(p.get("statut"))))throw new IllegalStateException("La période de temps est verrouillée ; sa réouverture est requise");}

    private void verifierRegles(long emp,long type,LocalDate du,LocalDate au,BigDecimal days){int notice=jdbc.queryForObject("SELECT preavis_min_jours FROM politique_demande_conge WHERE id=1",Integer.class);if(du.isBefore(LocalDate.now().plusDays(notice)))throw new IllegalArgumentException("Le préavis minimum n'est pas respecté");Boolean blocked=jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM periode_blocage_conge WHERE date_debut<=? AND date_fin>=?)",Boolean.class,au,du);if(blocked)throw new IllegalArgumentException("La période demandée est bloquée");
        BigDecimal minPct=jdbc.queryForObject("SELECT presence_min_pct FROM politique_demande_conge WHERE id=1",BigDecimal.class);if(minPct!=null)verifierPresence(emp,du,au,minPct);
        Boolean absence=jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM absence WHERE employe_id=? AND date_debut<=? AND date_fin>=?)",Boolean.class,emp,au,du);if(absence)throw new IllegalArgumentException("Une absence enregistrée chevauche cette période");}
    public Map<String,Object> politique(){return jdbc.queryForMap("SELECT * FROM politique_demande_conge WHERE id=1");}
    @Transactional public Map<String,Object> modifierPolitique(int notice,BigDecimal presence,Integer reminder,BigDecimal lowBalance){if(notice<0||presence!=null&&(presence.signum()<0||presence.compareTo(BigDecimal.valueOf(100))>0)||reminder!=null&&reminder<1||lowBalance!=null&&lowBalance.signum()<0)throw new IllegalArgumentException("Paramètres de politique invalides");jdbc.update("UPDATE politique_demande_conge SET preavis_min_jours=?,presence_min_pct=?,rappel_validation_jours=COALESCE(?,rappel_validation_jours),seuil_solde_faible_jours=COALESCE(?,seuil_solde_faible_jours) WHERE id=1",notice,presence,reminder,lowBalance);return politique();}
    public List<Map<String,Object>> periodesBloquees(){return jdbc.queryForList("SELECT * FROM periode_blocage_conge ORDER BY date_debut");}
    @Transactional public Map<String,Object> ajouterPeriodeBloquee(LocalDate du,LocalDate au,String libelle){verifierDates(du,au);Long id=jdbc.queryForObject("INSERT INTO periode_blocage_conge(date_debut,date_fin,libelle) VALUES(?,?,?) RETURNING id",Long.class,du,au,libelle);return jdbc.queryForMap("SELECT * FROM periode_blocage_conge WHERE id=?",id);}
    @Transactional public void supprimerPeriodeBloquee(long id){if(jdbc.update("DELETE FROM periode_blocage_conge WHERE id=?",id)==0)throw new IllegalArgumentException("Période bloquée introuvable");}
    private void verifierPresence(long emp,LocalDate du,LocalDate au,BigDecimal pct){for(LocalDate d=du;!d.isAfter(au);d=d.plusDays(1)){List<Long> depts=jdbc.queryForList("SELECT departement_id FROM affectation WHERE employe_id=? AND date_affectation<=? AND (date_fin IS NULL OR date_fin>=?)",Long.class,emp,d,d);for(Long dept:depts){Integer total=jdbc.queryForObject("SELECT COUNT(DISTINCT employe_id) FROM affectation WHERE departement_id=? AND date_affectation<=? AND (date_fin IS NULL OR date_fin>=?)",Integer.class,dept,d,d);if(total==null||total==0)continue;Integer absent=jdbc.queryForObject("SELECT COUNT(DISTINCT employe_id) FROM demande_conge WHERE statut IN ('SOUMISE','VALIDEE_MANAGER','VALIDEE_RH') AND date_debut<=? AND date_fin>=? AND employe_id IN (SELECT employe_id FROM affectation WHERE departement_id=? AND date_affectation<=? AND (date_fin IS NULL OR date_fin>=?))",Integer.class,d,d,dept,d,d);int away=(absent==null?0:absent)+1;double presentPct=100.0*(total-Math.min(total,away))/total;if(presentPct+0.0001<pct.doubleValue())throw new IllegalArgumentException("Le quota minimal de présence du service ne serait pas respecté");}}}
    private BigDecimal calculerJours(long emp,LocalDate du,LocalDate au,boolean halfStart,boolean halfEnd,String unit){verifierDates(du,au);if(du.equals(au)&&halfStart&&halfEnd)throw new IllegalArgumentException("Une journée unique ne peut être réduite qu'à une demi-journée");BigDecimal total=BigDecimal.ZERO;for(LocalDate d=du;!d.isAfter(au);d=d.plusDays(1)){if(!jourTravaille(emp,d,unit))continue;BigDecimal part=BigDecimal.ONE;if(du.equals(au)&&(halfStart||halfEnd))part=new BigDecimal("0.5");else if((d.equals(du)&&halfStart)||(d.equals(au)&&halfEnd))part=new BigDecimal("0.5");total=total.add(part);}return total.setScale(2,RoundingMode.HALF_UP);}
    public BigDecimal joursAbsence(long employeId,LocalDate du,LocalDate au,long typeCongeId){Map<String,Object> t=type(typeCongeId);return calculerJours(employeId,du,au,false,false,(String)t.get("unite_decompte"));}
    public BigDecimal joursPourDemandePeriode(long emp,LocalDate originalStart,LocalDate originalEnd,boolean halfStart,boolean halfEnd,LocalDate du,LocalDate au,long typeId){Map<String,Object>t=type(typeId);LocalDate from=du.isAfter(originalStart)?du:originalStart,to=au.isBefore(originalEnd)?au:originalEnd;if(to.isBefore(from))return BigDecimal.ZERO;return calculerJours(emp,from,to,halfStart&&from.equals(originalStart),halfEnd&&to.equals(originalEnd),(String)t.get("unite_decompte"));}
    public BigDecimal joursAbsenceCalendaires(long emp,LocalDate du,LocalDate au){return calculerJours(emp,du,au,false,false,"OUVRES");}
    private boolean jourTravaille(long emp,LocalDate d,String unit){Boolean holiday=jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM jour_ferie WHERE date=?)",Boolean.class,d);if(holiday)return false;Integer planned=jdbc.queryForObject("SELECT COUNT(*) FROM planning WHERE employe_id=? AND date=?",Integer.class,emp,d);if(planned!=null&&planned>0)return jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM planning WHERE employe_id=? AND date=? AND (type='TRAVAIL' OR (type IN ('CONGE','ABSENCE') AND (type_avant_conge='TRAVAIL' OR genere_pour_conge=true)))",Boolean.class,emp,d);Boolean hasRegime=jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM employe_regime WHERE employe_id=? AND date_debut<=? AND (date_fin IS NULL OR date_fin>=?))",Boolean.class,emp,d,d);Integer shifts=jdbc.queryForObject("SELECT COUNT(*) FROM employe_regime er JOIN horaire_type h ON h.regime_travail_id=er.regime_travail_id WHERE er.employe_id=? AND er.date_debut<=? AND (er.date_fin IS NULL OR er.date_fin>=?) AND h.jour_semaine=? AND h.travaille=true",Integer.class,emp,d,d,d.getDayOfWeek().getValue());if(Boolean.TRUE.equals(hasRegime))return shifts!=null&&shifts>0;if("OUVRES".equals(unit))return d.getDayOfWeek().getValue()<=5;return d.getDayOfWeek()!=DayOfWeek.SUNDAY;}
    private BigDecimal joursRestants(Map<String,Object>d){LocalDate start=date(d,"date_debut"),end=date(d,"date_fin"),from=LocalDate.now().isBefore(start)?start:LocalDate.now().plusDays(1);if(from.isAfter(end))return BigDecimal.ZERO;Map<String,Object>t=type(num(d,"type_conge_id"));BigDecimal remainder=calculerJours(num(d,"employe_id"),from,end,false,bool(d,"demi_journee_fin"),(String)t.get("unite_decompte"));return remainder.min(dec(d,"nb_jours"));}
    private void libererReservation(Map<String,Object>d,String email,String reason){Map<String,Object>t=type(num(d,"type_conge_id"));if(Boolean.TRUE.equals(t.get("debite_solde"))){long sid=soldeVerrouille(num(d,"employe_id"),num(d,"type_conge_id"),date(d,"date_debut").getYear());BigDecimal n=dec(d,"nb_jours");int updated=jdbc.update("UPDATE solde_conge SET en_attente=GREATEST(0,en_attente-?) WHERE id=?",n,sid);if(updated>0)mouvement(sid,"LIBERATION",n,num(d,"id"),reason,email,"DEMANDE:"+num(d,"id")+":LIBERATION");}}
    private void mouvement(long sid,String type,BigDecimal n,long demande,String reason,String email,String key){jdbc.update("INSERT INTO mouvement_solde(solde_conge_id,type,quantite,demande_id,date,motif,cree_par_id,cle_idempotence) VALUES(?,?,?,?,CURRENT_DATE,?,?,?) ON CONFLICT(solde_conge_id,cle_idempotence) WHERE cle_idempotence IS NOT NULL DO NOTHING",sid,type,n,demande,reason,userId(email),key);}
    private long soldeVerrouille(long emp,long type,int year){jdbc.update("INSERT INTO solde_conge(employe_id,type_conge_id,annee) VALUES(?,?,?) ON CONFLICT(employe_id,type_conge_id,annee) DO NOTHING",emp,type,year);return jdbc.queryForObject("SELECT id FROM solde_conge WHERE employe_id=? AND type_conge_id=? AND annee=? FOR UPDATE",Long.class,emp,type,year);}
    private Map<String,Object> demande(long id){return jdbc.queryForMap("SELECT * FROM demande_conge WHERE id=?",id);}private Map<String,Object> demandeVerrouillee(long id){return jdbc.queryForMap("SELECT * FROM demande_conge WHERE id=? FOR UPDATE",id);}
    private Map<String,Object> type(long id){return jdbc.queryForMap("SELECT * FROM type_conge WHERE id=? AND actif=true",id);}private long employeConnecte(String email){return jdbc.queryForObject("SELECT e.id FROM employe e JOIN candidat c ON c.id=e.candidat_id WHERE lower(c.email)=lower(?)",Long.class,email);}private int userId(String email){return jdbc.queryForObject("SELECT id FROM utilisateur WHERE lower(email)=lower(?)",Integer.class,email);}private boolean rh(String email){return jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM utilisateur u JOIN role r ON r.id=u.role_id WHERE lower(u.email)=lower(?) AND r.code IN ('RH','ADMIN'))",Boolean.class,email);}
    private boolean managerAutorise(long employee,String email,LocalDate date){Long manager=jdbc.query("SELECT a.manager_id FROM affectation a WHERE a.employe_id=? AND a.date_affectation<=? AND (a.date_fin IS NULL OR a.date_fin>=?) ORDER BY a.date_affectation DESC LIMIT 1",rs->rs.next()?rs.getLong(1):null,employee,date,date);Long actor=jdbc.query("SELECT e.id FROM employe e JOIN candidat c ON c.id=e.candidat_id WHERE lower(c.email)=lower(?)",rs->rs.next()?rs.getLong(1):null,email);if(actor==null)return false;if(Objects.equals(manager,actor))return true;return jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM delegation_validation WHERE manager_id=? AND delegue_id=? AND date_debut<=? AND date_fin>=?)",Boolean.class,manager,actor,date,date);}
    private void verifierDuree(Map<String,Object>type,BigDecimal jours){Object max=type.get("duree_max_jours");if(max!=null&&jours.compareTo(new BigDecimal(max.toString()))>0)throw new IllegalArgumentException("La durée maximale de ce type de congé est dépassée");}
    private void verifierDates(DemandeCongeRequest r){verifierDates(r.dateDebut(),r.dateFin());if(r.demiJourneeDebut()==null||r.demiJourneeFin()==null)throw new IllegalArgumentException("Les indicateurs de demi-journée sont requis");}private void verifierDates(LocalDate du,LocalDate au){if(au.isBefore(du))throw new IllegalArgumentException("La date de fin précède la date de début");}
    private long num(Map<String,Object>m,String k){return ((Number)m.get(k)).longValue();}private LocalDate date(Map<String,Object>m,String k){return ((Date)m.get(k)).toLocalDate();}private boolean bool(Map<String,Object>m,String k){return Boolean.TRUE.equals(m.get(k));}private BigDecimal dec(Map<String,Object>m,String k){return new BigDecimal(m.get(k).toString());}
}
